INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Preferred stock redemption premium reduces EPS numerator
(2, 'Earnings Per Share', 'Elmsford Industries redeems 5,000 shares of preferred stock at $120 per share when the carrying amount is $100 per share. Net income for 2025 is $800,000 with 200,000 weighted-average common shares. No other preferred stock is outstanding. What is basic EPS?', '["$3.50", "$4.00", "$3.00", "$3.75"]'::jsonb, 0, 'Under ASC 260-10-45-11A, the excess of the redemption price over carrying amount ($120 − $100 = $20 per share x 5,000 = $100,000) is treated as a return to preferred shareholders and deducted from the basic EPS numerator. Basic EPS = ($800,000 − $100,000) / 200,000 = $3.50. Choosing $4.00 ignores the redemption premium entirely, treating it as if redeeming preferred stock at par has no effect on income available to common shareholders.', 'medium', 2),

-- Q2: medium / L3 — Stock split requires retroactive adjustment of prior-period EPS
(2, 'Earnings Per Share', 'Glenridge Corp. reported basic EPS of $6.00 for Year 1 ($900,000 net income, 150,000 shares). On April 1 of Year 2, Glenridge executed a 3-for-1 stock split. Year 2 net income totaled $1,350,000 with 450,000 post-split shares outstanding throughout Year 2. When preparing comparative financial statements, how should the controller present EPS across both years?', '["Year 1 restated to $2.00 and Year 2 reported as $3.00", "Year 1 kept at $6.00 and Year 2 reported as $3.00", "Year 1 restated to $2.00 and Year 2 reported as $1.00", "Year 1 kept at $6.00 and Year 2 reported as $6.00"]'::jsonb, 0, 'Under ASC 260-10-55-12, stock splits require retroactive adjustment of all prior-period EPS data presented for comparability. Year 1 shares are restated to 450,000 (150,000 × 3), yielding $900,000 / 450,000 = $2.00. Year 2 EPS is $1,350,000 / 450,000 = $3.00. Keeping Year 1 at $6.00 destroys comparability because users would be comparing pre-split per-share amounts with post-split figures, creating a misleading impression of earnings decline.', 'medium', 3),

-- Q3: medium / L3 — Contingently issuable shares: revenue milestone not yet met
(2, 'Earnings Per Share', 'Haversham Group acquired a subsidiary in 2024 with an earn-out clause requiring issuance of 30,000 additional shares if subsidiary annual revenue exceeds $5 million in any year through 2027. Subsidiary revenue was $4.2 million for 2025. Management forecasts revenue of $5.3 million for 2026. Analyze the proper treatment of these contingent shares for the 2025 diluted EPS computation.', '["Include all 30,000 shares because management projects the revenue target will be met in 2026", "Include a proportional allocation of 25,200 shares ($4.2M / $5M × 30,000)", "Exclude the shares because the $5 million revenue condition is not satisfied at the 2025 reporting date", "Include all 30,000 shares because the earn-out contingency period has not yet expired"]'::jsonb, 2, 'Under ASC 260-10-45-52, contingently issuable shares dependent on a future earnings or revenue condition are included in diluted EPS only if the condition is currently satisfied — treating the reporting date as if it were the end of the contingency period. Since 2025 revenue of $4.2 million falls below the $5 million threshold, the condition is not met and the 30,000 shares are excluded. Management forecasts of future performance are irrelevant to the current-period test.', 'medium', 3),

-- Q4: easy / L1 — Treasury shares excluded from weighted-average
(2, 'Earnings Per Share', 'Under ASC 260, how are treasury shares treated in the weighted-average common shares calculation for basic EPS?', '["They are excluded from the weighted-average from the date of repurchase", "They are included in the weighted-average for the full year", "They are excluded only if held for more than six months", "They reduce shares only in the period following repurchase"]'::jsonb, 0, 'Under ASC 260-10-45-10, treasury shares are excluded from the weighted-average share count from the date they are repurchased. Shares outstanding means shares issued less shares held in treasury. Including treasury shares would overstate the denominator and understate EPS, failing to reflect that repurchased shares no longer participate in earnings.', 'easy', 1),

-- Q5: medium / L2 — Dividend reinvestment plan (DRIP) shares in weighted-average
(2, 'Earnings Per Share', 'Grantham Holdings has 200,000 shares outstanding on January 1 and operates a dividend reinvestment plan (DRIP). On each quarterly dividend date — March 31, June 30, September 30, and December 31 — 2,000 new shares are issued to reinvesting shareholders. What is the weighted-average number of shares for basic EPS?', '["203,000", "208,000", "206,000", "200,000"]'::jsonb, 0, 'Under ASC 260-10-45-10, DRIP shares are included from their issuance date. March 31 issuance: 2,000 x 9/12 = 1,500. June 30: 2,000 x 6/12 = 1,000. September 30: 2,000 x 3/12 = 500. December 31: 2,000 x 0/12 = 0. Total DRIP contribution = 3,000, plus base 200,000 = 203,000. Choosing 208,000 incorrectly treats all 8,000 DRIP shares as outstanding for the full year instead of weighting each from its issuance date.', 'medium', 2),

-- Q6: medium / L2 — Shares issued for services weighted from service date
(2, 'Earnings Per Share', 'Alderton Consulting has 80,000 shares outstanding on January 1, 2025. On March 1, the company issues 6,000 shares to a law firm as payment for legal services rendered during January and February. For basic EPS, from what date should the 6,000 shares be included in the weighted-average?', '["March 1, when the shares were issued", "January 1, when the services were performed", "February 1, the midpoint of the service period", "December 31, at year-end"]'::jsonb, 1, 'Under ASC 260-10-45-19, shares issued for services are included in the weighted-average from the date the services are rendered, not the issuance date. Since the legal services were rendered during January and February, the shares relate to that period. Choosing March 1 (issuance date) would understate the weighted-average shares for two months when the economic substance of the share issuance had already occurred.', 'medium', 2),

-- Q7: hard / L4 — Dual-class common stock requiring separate EPS
(2, 'Earnings Per Share', 'Langston Corp. has two classes of common stock: 300,000 Class A shares entitled to $1.50 per share in dividends before any distribution to Class B, and 200,000 Class B shares that receive all remaining dividends. Net income is $1,100,000 and total dividends declared are $850,000. After the Class A preference ($450,000), Class B receives $400,000. Undistributed earnings are $250,000, allocated entirely to Class B per the articles. Under ASC 260, evaluate the basic EPS presentation.', '["A single blended EPS of $2.20 is reported for both classes combined", "Only Class B EPS is reported since Class A has a fixed preference", "Separate EPS is required: Class A EPS is $1.50 and Class B EPS is $3.25", "Separate EPS is required: Class A EPS is $2.20 and Class B EPS is $2.20"]'::jsonb, 2, 'Under ASC 260-10-45-60B, entities with multiple classes of common stock must compute EPS separately for each class using the two-class method. Class A receives $450,000 distributed / 300,000 = $1.50. Class B receives $400,000 distributed + $250,000 undistributed / 200,000 = $3.25. Reporting a single blended figure obscures the different economic participation rights of each class and violates ASC 260 disclosure requirements.', 'hard', 4),

-- Q8: medium / L2 — Year-to-date vs quarterly weighted-average shares
(2, 'Earnings Per Share', 'Briarwood Inc. had 100,000 shares outstanding for Q1, then issued 50,000 shares on April 1. Q1 net income was $200,000 and Q2 net income was $375,000. An analyst computes year-to-date EPS as ($200,000 + $375,000) / 150,000 = $3.83. What is the correct year-to-date basic EPS for the six months ended June 30?', '["$3.83", "$4.17", "$3.75", "$4.60"]'::jsonb, 3, 'Under ASC 260-10-45-10, year-to-date weighted-average shares are computed over the entire period: (100,000 × 3/6) + (150,000 × 3/6) = 125,000. Year-to-date EPS = $575,000 / 125,000 = $4.60. The analyst erred by using the period-end share count (150,000) rather than the time-weighted average. The weighted-average reflects shares available to absorb earnings over the full six-month period.', 'medium', 2),

-- Q9: easy / L1 — Par value irrelevance to EPS
(2, 'Earnings Per Share', 'Under ASC 260, does the par value of common stock affect the computation of basic or diluted earnings per share?', '["No — par value has no effect on EPS calculations", "Yes — par value determines the denominator", "Yes — par value is deducted from the numerator", "Yes — only no-par stock is used in EPS calculations"]'::jsonb, 0, 'Under ASC 260, EPS uses net income (adjusted for preferred dividends) as the numerator and weighted-average common shares outstanding as the denominator. Par value is a legal concept related to minimum capitalization and has no bearing on EPS. The denominator counts shares, not dollar values. Confusing par value with share count would lead to fundamentally incorrect EPS results.', 'easy', 1),

-- Q10: medium / L2 — Induced conversion premium effect on EPS
(2, 'Earnings Per Share', 'Waverton Corp. has $500,000 of 6% convertible bonds (each $1,000 bond converts to 20 shares). To encourage conversion, Waverton offers bondholders an additional 2 shares per bond as an inducement. All bonds convert on July 1. Waverton has 200,000 common shares and net income of $1,000,000. The tax rate is 25%. How does the inducement affect the diluted EPS denominator?', '["Only the original 10,000 conversion shares are included; inducement shares are ignored", "The additional 1,000 inducement shares (500 x 2) are included in dilutive shares along with the original 10,000 conversion shares", "The inducement reduces the numerator but does not affect the denominator", "All inducement shares are treated as a stock dividend"]'::jsonb, 1, 'Under ASC 470-20-40 and ASC 260, when an entity offers additional consideration to induce conversion, the fair value of the inducement is expensed. For diluted EPS, the if-converted method includes all shares issuable upon conversion — both the original 10,000 shares and the 1,000 additional inducement shares — in the denominator. Excluding inducement shares would understate dilution and overstate diluted EPS.', 'medium', 2),

-- Q11: easy / L2 — Diluted EPS cannot exceed basic EPS
(2, 'Earnings Per Share', 'Allendale Corp. reports basic EPS of $3.00. After applying the treasury stock method to outstanding options and the if-converted method to convertible bonds, the controller computes diluted EPS of $3.15. What conclusion should the controller reach?', '["Diluted EPS of $3.15 should be reported as calculated", "The controller should report diluted EPS equal to basic EPS of $3.00 without further analysis", "The convertible bonds are antidilutive and must be excluded from diluted EPS", "Both the options and bonds should be excluded from diluted EPS"]'::jsonb, 2, 'Under ASC 260-10-45-17, diluted EPS cannot exceed basic EPS. If a security''s inclusion raises EPS above the basic figure, that security is antidilutive and must be excluded. Since the bonds'' per-share impact caused diluted EPS ($3.15) to exceed basic EPS ($3.00), the bonds are antidilutive. The controller should re-test without the bonds. Simply reporting $3.15 violates the fundamental constraint.', 'easy', 2),

-- Q12: hard / L4 — Contracts settleable in stock or cash at counterparty's option
(2, 'Earnings Per Share', 'Halstead Corp. issues an instrument that allows the holder (not the company) to elect settlement in either 10,000 common shares or $500,000 cash. The average market price is $40 per share. Net income is $600,000 with 200,000 weighted-average shares. The CFO proposes using the treasury stock method because the company expects cash settlement. Evaluate the CFO''s position under ASC 260.', '["Correct — the company''s intent to settle in cash means the instrument is excluded from diluted EPS", "Incorrect — all share-settleable instruments use the if-converted method regardless of settlement terms", "Correct — counterparty-option instruments are excluded from EPS until settlement occurs", "Incorrect — when the counterparty controls the settlement choice, the entity must assume the more dilutive of share or cash settlement for diluted EPS"]'::jsonb, 3, 'Under ASC 260-10-45-35 through 45-37, when the counterparty controls the settlement choice, the more dilutive alternative must be assumed for diluted EPS. Because the holder may choose shares, the entity cannot rely on its own cash-settlement intent. The more dilutive assumption (share settlement adding 10,000 shares) must be used. The CFO''s cash-settlement argument applies only when the entity controls the settlement election.', 'hard', 4),

-- Q13: easy / L1 — Discontinued operations per-share presentation requirement
(2, 'Earnings Per Share', 'Under ASC 260, where may a public entity present per-share amounts for discontinued operations?', '["Only on the face of the income statement", "On the face of the income statement or in the notes to the financial statements", "Only in the notes to the financial statements", "In management''s discussion and analysis only"]'::jsonb, 1, 'Under ASC 260-10-45-3, per-share amounts for discontinued operations may be presented either on the face of the income statement or in the notes. This differs from income from continuing operations and net income, which must be presented on the face. Requiring income statement face presentation only is overly restrictive and does not reflect the flexibility ASC 260 provides for this specific line item.', 'easy', 1),

-- Q14: hard / L4 — Contingent shares with EPS-based trigger (circular calculation)
(2, 'Earnings Per Share', 'Meridian Corp. has net income of $900,000 and 200,000 weighted-average shares. Under an acquisition agreement, 50,000 additional shares will be issued if basic EPS exceeds $4.00 in 2025. Before considering the contingent shares, basic EPS is $4.50. If the 50,000 shares are included in diluted EPS, EPS drops to $3.60. The controller is uncertain whether to include the contingent shares. Evaluate the correct treatment.', '["Include the 50,000 shares in diluted EPS because the current-period EPS condition ($4.50 > $4.00) is met, even though inclusion reduces EPS below $4.00", "Exclude the 50,000 shares because including them would reduce EPS below the $4.00 threshold", "Include only a proportional number of shares to bring EPS exactly to $4.00", "Exclude the shares from both basic and diluted EPS until the period ends"]'::jsonb, 0, 'Under ASC 260-10-45-52, contingently issuable shares based on an earnings condition are included in diluted EPS if the condition is currently satisfied at the reporting date. Since current-period EPS of $4.50 exceeds the $4.00 threshold, the condition is met and all 50,000 shares are included in diluted EPS — even though their inclusion reduces EPS below $4.00. The circularity does not override the test. Excluding shares because of the circular effect misapplies the standard.', 'hard', 4),

-- Q15: hard / L4 — Net loss allocation to participating securities (asymmetry)
(2, 'Earnings Per Share', 'Hargrove Holdings reports a net loss of $600,000 with 200,000 common shares and 100,000 fully participating preferred shares. The preferred shares contractually participate in dividends equally with common but have no contractual obligation to absorb losses. The controller allocates $200,000 of the loss to preferred under the two-class method (one-third of the loss). Evaluate the controller''s approach.', '["Correct — losses are allocated proportionally to all participating securities regardless of contractual obligations", "Correct — the two-class method requires allocation of both income and losses to participating securities", "Incorrect — losses are not allocated to participating preferred unless the security has a contractual obligation to fund losses; the full $600,000 loss is allocated to common, producing basic EPS of $(3.00)", "Incorrect — losses are always split evenly between common and preferred shares"]'::jsonb, 2, 'Under ASC 260-10-45-63A, net losses are allocated to participating securities in the two-class method only if the security has a contractual obligation to share in losses (e.g., funding deficit). Absent such an obligation, the full loss is allocated to common shareholders. Basic EPS = $(600,000) / 200,000 = $(3.00). The controller''s proportional allocation incorrectly reduces the loss per common share by attributing losses to preferred holders with no loss-sharing obligation.', 'hard', 4),

-- Q16: hard / L3 — Written put options: reverse treasury stock method creates dilution
(2, 'Earnings Per Share', 'Sycamore Holdings wrote put options obligating it to repurchase 20,000 of its own shares at $50 per share if holders exercise. During 2025, the average market price was $40 per share. The CFO excludes the written puts from diluted EPS, reasoning that repurchasing shares reduces the denominator and is therefore antidilutive. Analyze whether the CFO''s exclusion is correct.', '["Correct — written puts always reduce the share count and are inherently antidilutive", "Correct — puts are excluded from diluted EPS unless actually exercised during the period", "Incorrect — when the put exercise price exceeds market price, the reverse treasury stock method applies: assume issuance of 25,000 shares at $40 to fund repurchase of 20,000 at $50, adding 5,000 net incremental shares to the denominator", "Incorrect — the full 20,000 shares under the put contract are added to the denominator without any reverse treasury stock adjustment"]'::jsonb, 2, 'Under ASC 260-10-45-35, written put options where the exercise price exceeds the average market price are potentially dilutive. The reverse treasury stock method assumes the entity issues enough shares at market ($50 × 20,000 = $1,000,000 / $40 = 25,000 shares) to fund the repurchase obligation (20,000 shares at $50). The net effect adds 5,000 incremental shares to the denominator. The CFO''s reasoning fails because it ignores the assumed share issuance needed to generate cash for the repurchase.', 'hard', 3),

-- Q17: easy / L1 — Subscribed shares not yet issued
(2, 'Earnings Per Share', 'Under ASC 260, how are shares subscribed but not yet issued treated for basic EPS purposes?', '["They are included from the subscription date", "They are included at 50% of the subscribed amount", "They are included only if fully paid", "They are not included in the weighted-average share count until they are issued"]'::jsonb, 3, 'Under ASC 260-10-45-10, the weighted-average share count includes only shares that are issued and outstanding. Shares that have been subscribed but not yet issued are not outstanding and therefore are excluded from basic EPS. Once the subscription is fulfilled and shares are actually issued, they enter the weighted-average from the issuance date. Including unissued subscribed shares would overstate shares outstanding.', 'easy', 1),

-- Q18: easy / L1 — Stock dividends require retroactive EPS adjustment
(2, 'Earnings Per Share', 'On June 15, 2025, Pemberton Corp. declares a 10% common stock dividend distributed on July 15 to shareholders of record on June 30. The company had 400,000 shares outstanding before the dividend. When preparing 2025 annual EPS, from what date should the 40,000 additional shares be reflected in the weighted-average?', '["Retroactively from January 1 — stock dividends are treated as if outstanding for the entire period", "From July 15, the distribution date", "From June 15, the declaration date", "From June 30, the record date"]'::jsonb, 0, 'Under ASC 260-10-55-12, stock dividends (and stock splits) are given retroactive recognition in the EPS denominator. The 40,000 additional shares are treated as if they had been outstanding from the beginning of the earliest period presented, not from the declaration, record, or distribution date. This retroactive treatment ensures that per-share data is comparable across periods and reflects the changed capital structure.', 'easy', 1),

-- Q19: medium / L2 — Shares issued in stock subscription installments
(2, 'Earnings Per Share', 'Brookfield Corp. has 100,000 shares outstanding on January 1. On April 1, it issues 20,000 shares under a stock subscription, with subscribers paying 40% ($10 of $25 per share) at issuance. The remaining 60% is collected on October 1. What is the weighted-average share count for basic EPS?', '["120,000", "108,000", "115,000", "100,000"]'::jsonb, 2, 'Under ASC 260-10-45-10, once shares are issued they enter the weighted-average count from the issuance date, regardless of whether full payment has been received. The 20,000 shares were issued on April 1: 100,000 x 12/12 = 100,000; plus 20,000 x 9/12 = 15,000; total = 115,000. The October payment is irrelevant because the shares were already issued. Choosing 108,000 incorrectly weights shares from the date of full payment.', 'medium', 2),

-- Q20: medium / L3 — Interim period option dilution testing
(2, 'Earnings Per Share', 'Stratton Corp. has 10,000 stock options with an exercise price of $40. In Q1 2025, the average market price is $35 (options out of the money). In Q2, the average market price rises to $55. For year-to-date interim EPS through June 30, the six-month average market price is $45. Analyze whether the options should be included in year-to-date diluted EPS.', '["Yes — the year-to-date average market price of $45 exceeds the $40 exercise price, so the options are dilutive for the six-month period", "No — because the options were antidilutive in Q1, they must be excluded from the year-to-date computation", "Yes — but only the Q2 incremental shares are included in the year-to-date calculation", "No — options must be dilutive in every quarter to be included in year-to-date diluted EPS"]'::jsonb, 0, 'Under ASC 260-10-45-29 and ASC 270, year-to-date diluted EPS uses the year-to-date average market price to test dilution independently. Since the six-month average of $45 exceeds the $40 exercise price, the options are dilutive for the year-to-date period even though they were antidilutive in Q1 taken alone. Each reporting period is evaluated on its own. Requiring dilution in every quarter imposes a condition not found in ASC 260.', 'medium', 3),

-- Q21: easy / L1 — Definition of incremental shares under treasury stock method
(2, 'Earnings Per Share', 'Under the treasury stock method, what does the term "incremental shares" represent?', '["The total number of shares issuable upon exercise of options", "The number of shares repurchased with the option proceeds", "The difference between shares outstanding before and after exercise", "The excess of shares assumed issued upon option exercise over shares assumed repurchased with the proceeds"]'::jsonb, 3, 'Under ASC 260-10-45-23, the treasury stock method assumes options are exercised and proceeds are used to repurchase shares at the average market price. Incremental shares equal the difference between shares assumed issued and shares assumed repurchased. Only this net amount is added to the denominator. Confusing incremental shares with total issuable shares would overstate dilution significantly.', 'easy', 1),

-- Q22: medium / L3 — Share lending arrangements in equity offerings
(2, 'Earnings Per Share', 'Whitmore Corp. enters a share lending arrangement, lending 50,000 of its own treasury shares to an investment bank as part of a convertible note offering. The shares are returnable and the arrangement is expected to be temporary. Net income is $1,200,000 with 400,000 common shares outstanding. The CFO includes the 50,000 loaned shares in the basic EPS denominator. Evaluate this treatment.', '["Incorrect — loaned shares in a share lending arrangement entered in connection with a convertible offering are excluded from basic EPS under ASC 260-10-45-13A", "Correct — all issued shares including loaned shares must be in the basic EPS denominator", "Incorrect — loaned shares are included in diluted EPS but not basic EPS", "Correct — share lending arrangements are irrelevant to EPS calculations"]'::jsonb, 0, 'Under ASC 260-10-45-13A, shares issued or loaned in a share lending arrangement entered in contemplation of a convertible debt offering are excluded from basic EPS if the shares are expected to be returned. These shares are not considered outstanding because they do not participate in earnings. Including them would inflate the denominator and understate basic EPS, misrepresenting earnings available per common share.', 'medium', 3),

-- Q23: medium / L3 — Retrospective EPS adjustment for prior-period error
(2, 'Earnings Per Share', 'Fernwick Corp. reported basic EPS of $5.00 for Year 1 based on net income of $1,000,000 and 200,000 shares. In Year 2, Fernwick discovered it had understated Year 1 cost of goods sold by $200,000 (pretax). The tax rate is 25%. When presenting comparative statements, what should Year 1 basic EPS be restated to?', '["$4.50", "$4.25", "$4.00", "$5.00"]'::jsonb, 1, 'Under ASC 250-10-45-1 and ASC 260, a prior-period error requires retrospective restatement. The $200,000 COGS understatement reduces Year 1 net income by $150,000 after tax ($200,000 x 75%), to $850,000. Restated EPS = $850,000 / 200,000 = $4.25. Choosing $4.00 incorrectly fails to tax-effect the adjustment, and choosing $5.00 ignores the restatement requirement entirely. Comparative EPS must reflect the corrected amounts.', 'medium', 3),

-- Q24: hard / L4 — Control number: continuing operations governs dilution testing for all line items
(2, 'Earnings Per Share', 'Ridgewood Corp. reports income from continuing operations of $500,000 and a discontinued operations gain of $300,000 (total net income $800,000) with 200,000 shares. Outstanding stock options produce 8,000 incremental shares under the treasury stock method. Including options reduces continuing-operations per-share from $2.50 to $2.40 (dilutive), but the discontinued-operations per-share figure rises when options are included. The CFO proposes excluding options from the discontinued operations per-share amount. Evaluate the CFO''s proposal.', '["Correct — options should only be included for line items where they reduce per-share amounts", "Correct — discontinued operations EPS is calculated independently of continuing operations", "Incorrect — the control number is income from continuing operations; since options are dilutive for that figure, they must be included for all per-share amounts, even if antidilutive for a specific component", "Incorrect — options must be excluded from all line items because they are antidilutive for discontinued operations"]'::jsonb, 2, 'Under ASC 260-10-45-19, income from continuing operations serves as the control number for dilution testing. If a security is dilutive with respect to continuing operations, it is included in the diluted per-share computation for every reported income component — continuing operations, discontinued operations, and net income — even if it would be antidilutive for an individual component. The CFO''s proposal to selectively exclude options violates the single-control-number principle.', 'hard', 4),

-- Q25: easy / L1 — EPS precision requirements
(2, 'Earnings Per Share', 'Under common practice and SEC guidance, to how many decimal places should a public entity present earnings per share amounts?', '["The nearest dollar (no decimal places)", "The nearest tenth (one decimal place)", "The nearest cent (two decimal places)", "The nearest thousandth (three decimal places)"]'::jsonb, 2, 'Common practice and SEC requirements call for presentation of EPS to the nearest cent (two decimal places). Presenting EPS to fewer than two decimal places would obscure meaningful differences between basic and diluted EPS. Presenting to three or more decimal places exceeds standard practice and is not required. The two-decimal convention balances precision with readability for financial statement users.', 'easy', 1),

-- Q26: medium / L2 — Preferred stock issued below par: excess carrying amount over issuance price
(2, 'Earnings Per Share', 'Caldwell Financial issues 8,000 shares of preferred stock at $90 per share (below the $100 par value). Two years later, Caldwell retires all preferred shares at par ($100 per share). Net income is $600,000 with 150,000 weighted-average common shares. What amount, if any, reduces the basic EPS numerator upon retirement?', '["$80,000", "$0 — retirement at par requires no EPS adjustment", "$800,000", "$160,000"]'::jsonb, 0, 'Under ASC 260-10-45-11A, when preferred stock is retired, the excess of the fair value of consideration paid (par of $100 x 8,000 = $800,000) over the carrying amount ($90 x 8,000 = $720,000) reduces the EPS numerator by $80,000. This $80,000 premium represents a return to preferred shareholders beyond their original investment. Choosing $0 incorrectly assumes retirement at par never affects EPS, ignoring the discount at original issuance.', 'medium', 2),

-- Q27: medium / L2 — Dividend equivalents on unvested shares create participating security
(2, 'Earnings Per Share', 'Woodfield Corp. grants 20,000 unvested restricted shares with nonforfeitable dividend rights — holders receive dividends equal to those paid on common stock even if they terminate before vesting. The company has 300,000 common shares and net income of $900,000. Under ASC 260, how should Woodfield compute basic EPS?', '["Using the standard formula, deducting no preferred dividends since restricted shares are common equity", "Using the treasury stock method, treating the restricted shares like options", "The unvested shares are completely ignored for both basic and diluted EPS", "Using the two-class method, because the nonforfeitable dividend rights make the unvested shares a participating security"]'::jsonb, 3, 'Under ASC 260-10-45-59A, unvested share-based payment awards with nonforfeitable dividend rights are participating securities. Basic EPS must be computed using the two-class method, which allocates undistributed earnings between common shareholders and the participating unvested shares. The treasury stock method applies to unvested awards without nonforfeitable dividends. Ignoring the awards entirely understates the allocation of earnings to other equity classes.', 'medium', 2),

-- Q28: medium / L3 — Quarterly vs annual dilution testing can differ
(2, 'Earnings Per Share', 'Ashford Corp. has 15,000 stock options with an exercise price of $30. Quarterly average market prices are: Q1 $25, Q2 $28, Q3 $42, Q4 $45. The full-year average is $35. The controller includes the options only in Q3 and Q4 diluted EPS and also includes them in the annual diluted EPS. Analyze whether the annual inclusion is correct.', '["Correct — the full-year average market price of $35 exceeds $30, so the options are dilutive for the annual period even though they were antidilutive in Q1 and Q2", "Incorrect — because options were antidilutive in Q1 and Q2, they must be excluded from annual diluted EPS", "Incorrect — annual diluted EPS must average the four quarterly diluted EPS figures", "Correct — but the annual incremental shares should equal the average of Q3 and Q4 incremental shares"]'::jsonb, 0, 'Under ASC 260-10-45-29, annual diluted EPS uses the annual average market price independently. Since $35 > $30, the options are dilutive for the annual period regardless of being antidilutive in certain quarters. Quarterly and annual dilution tests are independent computations. Requiring dilution in all quarters for annual inclusion adds a condition not in ASC 260. Annual incremental shares use the annual average, not an average of quarterly figures.', 'medium', 3),

-- Q29: medium / L3 — Reverse acquisition: historical EPS of legal acquiree restated
(2, 'Earnings Per Share', 'Pinnacle Corp. (legal acquirer) issues 150,000 shares to acquire Summit Inc. (legal acquiree), but Summit is determined to be the accounting acquirer under ASC 805 (reverse acquisition). Summit previously had 100,000 shares and basic EPS of $3.00. At what exchange ratio must Summit''s prior-period EPS be retroactively adjusted?', '["Summit''s prior-period EPS is restated using the exchange ratio to reflect the combined capital structure", "No restatement is needed because Pinnacle is the legal acquirer of the shares", "Summit''s prior-period EPS is restated only if Pinnacle''s shares are publicly traded", "Both entities'' prior-period EPS figures are averaged and presented as combined"]'::jsonb, 0, 'Under ASC 805-40-45-1 and ASC 260-10-45-61, in a reverse acquisition the accounting acquirer''s (Summit''s) historical EPS is retroactively restated by multiplying the pre-acquisition weighted-average shares by the exchange ratio established in the combination. This ensures comparability between periods. Choosing no restatement confuses the legal form (Pinnacle issued shares) with the accounting substance (Summit controls the combined entity).', 'medium', 3),

-- Q30: easy / L1 — Nonpublic entities and EPS disclosure requirements
(2, 'Earnings Per Share', 'A privately held manufacturing company with annual revenue of $50 million prepares U.S. GAAP financial statements. Its audit committee asks whether ASC 260 requires the company to present earnings per share. What is the correct answer?', '["EPS disclosure is not required for nonpublic entities under ASC 260", "All entities preparing U.S. GAAP financial statements must present EPS", "Nonpublic entities must present basic EPS but may omit diluted EPS", "EPS is required only if the entity has more than $100 million in total assets"]'::jsonb, 0, 'Under ASC 260-10-15-2, the EPS standard applies only to entities with publicly held common stock or potential common stock (i.e., public entities). A privately held company is not required to present EPS, though it may voluntarily do so. Requiring EPS of all GAAP preparers overstates the scope of ASC 260. The requirement is driven by public-market investor needs, not by entity size or revenue thresholds.', 'easy', 1)
;

COMMIT;
